        const y = interpolate(collapseSpring, [0, 1], [currentYOffset, 0]);
        const rot = interpolate(collapseSpring, [0, 1], [targetRot, 0]);
        const scale = Math.max(0, interpolate(collapseSpring, [0, 1], [1, 0]));
        
